package com.sumedha.commerce.product.entity; import com.sumedha.commerce.product.enums.ProductStatus; import jakarta.persistence.*; import java.math.*; import java.time.*; import java.util.*; @Entity @Table(name="products") public class Product{@Id @Column(name="product_id") private UUID id;private String sku,name,slug;@Column(name="short_description") private String shortDescription;private String description;@Column(name="category_id") private UUID categoryId;@Column(name="brand_id") private UUID brandId;private BigDecimal price;private String currency;@Enumerated(EnumType.STRING) private ProductStatus status;private boolean active;@Column(name="created_at") private Instant createdAt;@Column(name="updated_at") private Instant updatedAt;protected Product(){}public Product(String sku,String name,String slug,UUID c,UUID b,BigDecimal price,String currency){id=UUID.randomUUID();this.sku=sku;this.name=name;this.slug=slug;categoryId=c;brandId=b;this.price=price;this.currency=currency;status=ProductStatus.DRAFT;active=true;createdAt=Instant.now();updatedAt=createdAt;}@PreUpdate void touch(){updatedAt=Instant.now();}public UUID getId(){return id;}public String getSku(){return sku;}public String getName(){return name;}public String getSlug(){return slug;}public String getShortDescription(){return shortDescription;}public String getDescription(){return description;}public UUID getCategoryId(){return categoryId;}public UUID getBrandId(){return brandId;}public BigDecimal getPrice(){return price;}public String getCurrency(){return currency;}public ProductStatus getStatus(){return status;}public boolean isActive(){return active;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public void update(String n,String s,String shortDesc,String desc,UUID c,UUID b,BigDecimal pr,String cur,ProductStatus st,boolean a){name=n;slug=s;shortDescription=shortDesc;description=desc;categoryId=c;brandId=b;price=pr;currency=cur;status=st;active=a;}}
